   472	 *
   473	 * @param array<string,mixed> $updates
   474	 */
   475	function sync_article_index_entry(string $articleId, array $updates): bool
   476	{
   477	  $articleId = trim($articleId);
   478	  if ($articleId === '' || !file_exists(ADMIN_ARTICLES_SOURCE_PATH)) {
   479	    return false;
   480	  }
   481	
   482	  $raw = file_get_contents(ADMIN_ARTICLES_SOURCE_PATH);
   483	  if ($raw === false || trim($raw) === '') {
   484	    return false;
   485	  }
   486	  $items = json_decode($raw, true);
   487	  if (!is_array($items)) {
   488	    return false;
   489	  }
   490	
   491	  $changed = false;
   492	  foreach ($items as $idx => $item) {
   493	    if (!is_array($item)) {
   494	      continue;
   495	    }
   496	    if ((string) ($item['id'] ?? '') !== $articleId) {
   497	      continue;
   498	    }
   499	    foreach ($updates as $key => $value) {
   500	      $items[$idx][$key] = $value;
   501	    }
   502	    $changed = true;
   503	    break;
   504	  }
   505	
   506	  if (!$changed) {
   507	    return false;
   508	  }
   509	
   510	  $json = json_encode($items, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   511	  if ($json === false) {
   512	    return false;
   513	  }
   514	  $bytes = file_put_contents(ADMIN_ARTICLES_SOURCE_PATH, $json . PHP_EOL);
   515	  if ($bytes === false) {
   516	    return false;
   517	  }
   518	  sync_articles_index(true);
   519	  return true;
   520	}

