   119	function save_article_uploaded_image(string $articleId, array $fileInput): array
   120	{
   121	  $tmpName = (string) ($fileInput['tmp_name'] ?? '');
   122	  $originalName = (string) ($fileInput['name'] ?? 'image');
   123	  $size = (int) ($fileInput['size'] ?? 0);
   124	  $error = (int) ($fileInput['error'] ?? UPLOAD_ERR_NO_FILE);
   125	
   126	  if ($error !== UPLOAD_ERR_OK) {
   127	    throw new RuntimeException('Upload ảnh thất bại.');
   128	  }
   129	  if ($size <= 0 || $size > 8 * 1024 * 1024) {
   130	    throw new RuntimeException('Ảnh phải nhỏ hơn 8MB.');
   131	  }
   132	  if (!is_uploaded_file($tmpName)) {
   133	    throw new RuntimeException('File upload không hợp lệ.');
   134	  }
   135	
   136	  $finfo = finfo_open(FILEINFO_MIME_TYPE);
   137	  $mime = $finfo ? (string) finfo_file($finfo, $tmpName) : '';
   138	  if ($finfo) {
   139	    finfo_close($finfo);
   140	  }
   141	
   142	  $extMap = [
   143	    'image/jpeg' => 'jpg',
   144	    'image/png' => 'png',
   145	    'image/gif' => 'gif',
   146	    'image/webp' => 'webp',
   147	  ];
   148	  if (!isset($extMap[$mime])) {
   149	    throw new RuntimeException('Chỉ hỗ trợ JPG, PNG, GIF, WEBP.');
   150	  }
   151	
   152	  $base = pathinfo($originalName, PATHINFO_FILENAME);
   153	  $base = preg_replace('/[^a-zA-Z0-9_-]+/', '-', (string) $base) ?? 'image';
   154	  $base = trim($base, '-_');
   155	  if ($base === '') {
   156	    $base = 'image';
   157	  }
   158	
   159	  $stamp = new DateTimeImmutable('now');
   160	  $articleSlug = article_upload_safe_article_slug($articleId);
   161	  $dir = article_upload_dir($articleId, $stamp);
   162	  if (!is_dir($dir)) {
   163	    mkdir($dir, 0775, true);
   164	  }
   165	
   166	  $prefix = $articleSlug !== '' ? ($articleSlug . '-') : '';
   167	  $filename = $prefix . $base . '-' . $stamp->format('Ymd-His') . '-' . substr(md5((string) microtime(true)), 0, 6) . '.' . $extMap[$mime];
   168	  $target = $dir . '/' . $filename;
   169	
   170	  if (!move_uploaded_file($tmpName, $target)) {
   171	    throw new RuntimeException('Không lưu được ảnh upload.');
   172	  }
   173	
   174	  return [
   175	    'name' => $filename,
   176	    'size' => (int) (filesize($target) ?: 0),
   177	    'path' => $target,
   178	    'url' => article_upload_url($articleId, $filename, $stamp),
   179	    'public_path' => article_upload_public_path($articleId, $filename, $stamp),
   180	    'mime' => $mime,
   181	    'year' => $stamp->format('Y'),
   182	    'month' => $stamp->format('m'),
   183	  ];
   184	}
   185	
   186	/**
   187	 * Remove uploaded file in year/month upload dirs.
   188	 */
   189	function delete_article_uploaded_image(string $articleId, string $uploadName, string $uploadYear = '', string $uploadMonth = ''): bool
   190	{
   191	  $name = basename(trim($uploadName));
   192	  if ($name === '' || $name === '.' || $name === '..') {
   193	    return false;
   194	  }
   195	
   196	  $try = [];
   197	  $year = trim($uploadYear);
   198	  $month = trim($uploadMonth);
   199	  if (preg_match('/^\d{4}$/', $year) && preg_match('/^\d{2}$/', $month)) {
   200	    $try[] = rtrim(ADMIN_UPLOADS_DIR, '/') . '/articles/' . $year . '/' . $month . '/' . $name;
   201	  }
   202	
   203	  $root = rtrim(ADMIN_UPLOADS_DIR, '/') . '/articles';
   204	  if (is_dir($root)) {
   205	    foreach (scandir($root) ?: [] as $y) {
   206	      if ($y === '.' || $y === '..' || !preg_match('/^\d{4}$/', $y)) {
   207	        continue;
   208	      }
   209	      $yearDir = $root . '/' . $y;
   210	      if (!is_dir($yearDir)) {
   211	        continue;
   212	      }
   213	      foreach (scandir($yearDir) ?: [] as $m) {
   214	        if ($m === '.' || $m === '..' || !preg_match('/^\d{2}$/', $m)) {
   215	          continue;
   216	        }
   217	        $try[] = $yearDir . '/' . $m . '/' . $name;
   218	      }
   219	    }
   220	  }
   221	
   222	  foreach (array_unique($try) as $path) {
   223	    if (is_file($path)) {
   224	      return unlink($path);
   225	    }
   226	  }
   227	
   228	  return false;
   229	}
   230	
   231	/**
   232	 * Build stable slug prefix for filename filtering.
   233	 */
   234	function article_upload_safe_article_slug(string $articleId): string
   235	{
   236	  $value = trim($articleId);
   237	  $value = str_replace('\\', '/', $value);
   238	  $value = preg_split('/[?#]/', $value, 2)[0] ?? $value;
   239	
   240	  if (preg_match('~([a-zA-Z0-9/_\\-]+\\.html)~', $value, $matches) === 1) {
   241	    $value = (string) ($matches[1] ?? $value);
   242	  }
   243	
   244	  $value = trim($value, '/');
   245	  $value = str_replace('/', '-', $value);
   246	  $value = preg_replace('/\\.html$/i', '', $value) ?? $value;
   247	  $value = preg_replace('/[^a-zA-Z0-9\-_]+/', '-', $value) ?? '';
   248	  $value = trim((string) $value, '-_');
   249	
   250	  return strtolower($value);
   251	}
